// Capture reference outputs from the executable into a golden cache. Test infrastructure only.
import { spawn } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";

const EXE = "/workspace/dataset/test2_executable";
const lines = readFileSync("/tmp/harness/vectors.jsonl", "utf8").trim().split("\n");
// A NUL byte cannot be passed through argv at all, so those vectors are untestable here.
const vals = lines.map((l) => JSON.parse(l)).filter((v) => !v.includes("�"));

function run(cmd, args) {
  return new Promise((res) => {
    const p = spawn(cmd, args);
    let o = "", e = "";
    p.stdout.on("data", (d) => (o += d));
    p.stderr.on("data", (d) => (e += d));
    p.on("close", (c) => res({ o, e, c }));
    p.on("error", () => res({ o: "", e: "SPAWN_ERR", c: -1 }));
  });
}

const out = new Array(vals.length);
let idx = 0;
async function worker() {
  while (idx < vals.length) {
    const i = idx++;
    out[i] = await run(EXE, ["--a", vals[i]]);
  }
}
await Promise.all(Array.from({ length: 24 }, worker));

writeFileSync(
  "/tmp/harness/golden.jsonl",
  vals.map((v, i) => JSON.stringify({ v, ...out[i] })).join("\n") + "\n"
);
console.log("captured", vals.length, "vectors; skipped", lines.length - vals.length, "(NUL)");

